  ('utah-desert-remote-observatories', '2022-06-22', 'Supernova Remnant: The Veil Nebula', 'https://science.nasa.gov/image-article/apod-2022-june-22-supernova-remnant-the-veil-nebula/', true, 'https://assets.science.nasa.gov/dynamicimage/assets/science/cds/apod/apod/2022/june/Veil_Stocks_1080.jpg', 'The featured image shows a composite of long duration exposures of he Veil Nebula, the glowing gaseous remnants of a supernova that occurred about ten thousand years ago. Please see the explanation for more detailed information.'),
  ('utah-desert-remote-observatories', '2022-12-19', 'The Tadpole Nebula in Gas and Dust', 'https://science.nasa.gov/image-article/apod-2022-december-19-the-tadpole-nebula-in-gas-and-dust/', true, 'https://assets.science.nasa.gov/dynamicimage/assets/science/cds/apod/apod/2022/december/Tadpoles_Stocks_960.jpg', 'The featured image shows a glowing star forming region rich in glowing gas and dark dust. Two dusty pillars on the right resemble tadpoles. Please see the explanation for more detailed information.'),
  ('utah-desert-remote-observatories', '2024-01-29', 'The Pleiades: Seven Dusty Sisters', 'https://science.nasa.gov/image-article/apod-2024-january-29-the-pleiades-seven-dusty-sisters/', false, 'https://assets.science.nasa.gov/dynamicimage/assets/science/cds/apod/apod/2024/january/Pleiades_Stocks_2048.jpg', 'The famous Pleiades star cluster is shown surrounded by dust. Dust near the bright stars reflects blue light, but dust further away appears more red. Please see the explanation for more detailed information.')
